   $ex${"titre":"Sofía arrive à Séville","competence":"manier-langue","situation":"Sofía, élève de 3e, prépare un voyage à Séville. Elle présente son projet dans un texte, puis complète un tableau de conjugaisons.","documents":[{"id":"sofia","type":"texte","genre":"recit","titre":"El viaje de Sofía","blocs":["Soy Sofía y estudio español desde hace dos años. Mañana salgo hacia Sevilla con mi clase.","En 1492, Colón llega a América, nos explica el profesor. Vivo en Francia desde hace tres años."],"source":"Texte écrit pour l’exercice"},{"id":"verbos","type":"tableau","titre":"Los verbos de Sofía","colonnes":["Infinitivo","yo","tú","nosotros"],"lignes":[["tener","tengo","?","tenemos"],["venir","vengo","vienes","?"],["ser","soy","?","somos"],["estar","estoy","estás","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Range chaque phrase selon l’emploi du présent.","aide":"Cherche le repère de temps : « mañana », une date, « desde hace ».","type":"categories","categories":[{"id":"c0","texte":"Futur proche"},{"id":"c1","texte":"Présent historique"},{"id":"c2","texte":"Action commencée dans le passé"}],"items":[{"id":"i0","texte":"El sábado vuelo a Lima"},{"id":"i1","texte":"Vivo en Francia desde hace tres años"},{"id":"i2","texte":"Estudio español desde hace dos años"},{"id":"i3","texte":"Mañana salgo hacia Sevilla con mi clase"},{"id":"i4","texte":"En 1492, Colón llega a América"}]},{"enonce":"Complète le tableau.","aide":"Tener et venir diphtonguent, sauf à nosotros et vosotros.","type":"trous","segments":["tener (tú) → ",0," ; venir (nosotros) → ",1," ; ser (tú) → ",2," ; estar (nosotros) → ",3],"banque":["somos","tienes","eres","venimos","vienes","estamos"]},{"enonce":"Touche la forme du tableau qui porte un **accent écrit** sur la terminaison.","aide":"Un seul verbe de la liste a un accent écrit au présent.","type":"zone","document":"verbos","multiple":false},{"enonce":"Que cumule le verbe tener (tengo, tienes) ?","aide":"Compare tengo à tienes.","type":"choix","options":[{"id":"a","texte":"Un « yo » irrégulier et une diphtongue"},{"id":"b","texte":"Seulement une diphtongue au présent"},{"id":"c","texte":"Seulement un « yo » irrégulier"},{"id":"d","texte":"Aucune irrégularité au présent"}],"multiple":false}]}$ex$::jsonb,
