   $ex${"titre":"Verbes mixtes et pièges d’orthographe","competence":"manier-langue","situation":"Un tableau compare quatre verbes en -ir, puis Hugo écrit à son oncle pour choisir le dessert.","documents":[{"id":"mixtos","type":"tableau","titre":"Cuatro verbos en -ir","colonnes":["Verbo","Presente (yo)","Pasado (él)","Gerundio"],"lignes":[["sentir","siento","sintió","sintiendo"],["preferir","prefiero","prefirió","prefiriendo"],["dormir","duermo","durmió","durmiendo"],["pedir","pido","pidió","pidiendo"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"tio","type":"texte","genre":"lettre","titre":"Carta al tío","blocs":["Querido tío : hoy yo elijo el postre. Mi hermano prefiere la tarta y mi madre pide un helado. ¡Nos reímos mucho!"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes mixtes** : ceux qui diphtonguent au présent *et* s’affaiblissent ensuite.","aide":"Compare la colonne « Presente » : la voyelle change-t-elle en *ie* ou *ue* ?","type":"zone","document":"mixtos","multiple":true},{"enonce":"Que dire de *pedir*, dans ce tableau ?","aide":"Regarde la colonne « Presente (yo) » : *pido*, pas *piedo*.","type":"choix","options":[{"id":"a","texte":"Il diphtongue au présent comme sentir"},{"id":"b","texte":"Il s’affaiblit sans diphtonguer"},{"id":"c","texte":"Il ne change jamais de voyelle"},{"id":"d","texte":"Il diphtongue au gérondif"}],"multiple":false},{"enonce":"Complète au passé simple.","aide":"Le passé simple s’affaiblit à la 3e personne.","type":"trous","segments":["Anoche mi hermano ",0," doce horas."],"banque":["dormió","duerme","durmió","durmiendo"]},{"enonce":"Complète au subjonctif présent.","aide":"Au subjonctif présent, l’affaiblissement touche toutes les personnes.","type":"trous","segments":["Quiero que nosotros ",0," pizza."],"banque":["pedamos","pidan","pidamos","pedimos"]},{"enonce":"Touche le verbe dont le **g devient j** pour garder le son.","aide":"C’est le verbe *elegir*.","type"