   $ex$[{"cle":{"type":"zone","ids":["r0c1","r1c1","r2c1"]},"explication":"**siento, prefiero, duermo** : diphtongue au présent (*ie, ue*), affaiblissement au passé et au gérondif. *Pido* n’est qu’un affaiblissement."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Pedir** n’est pas mixte : *pido, pidió, pidiendo*, jamais de diphtongue."},{"cle":{"type":"trous","trous":[["durmio"]]},"affichage":"durmió","explication":"**Durmió** : *dormir* est mixte, il s’affaiblit au passé simple (*o → u*)."},{"cle":{"type":"trous","trous":[["pidamos"]]},"affichage":"pidamos","explication":"**Pidamos** : subjonctif présent, l’affaiblissement s’applique même à *nosotros*."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**Elijo** : le g de *elegir* devient *j* devant o."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c2","i4":"c0","i5":"c1"}},"explication":"Présent en *-o*, passé simple en *-ió*, gérondif en *-iendo*."}]$ex$::jsonb),
