   $ex${"titre":"Une invitation pour samedi","competence":"comprendre-langue","situation":"Laura organise une fête et invite son ami Pedro par message.","documents":[{"id":"fiesta","type":"dialogue","modele":"sms","titre":"Messages de Laura et Pedro","participants":[{"nom":"Laura","emoji":"👧","cote":"gauche"},{"nom":"Pedro","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Laura","texte":"¡Hola, Pedro! Quiero que vengas a mi fiesta el sábado."},{"qui":"Pedro","texte":"¡Genial! Creo que puedo ir. Espero que haya pizza."},{"qui":"Laura","texte":"Sí, y veo que tienes hambre. ¡Hasta el sábado!"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux verbes au subjonctif** des messages.","aide":"Ils suivent un verbe de volonté ou de souhait.","type":"zone","document":"fiesta","multiple":true},{"enonce":"Pourquoi Laura écrit-elle « Quiero que vengas » et non « Quiero que vienes » ?","aide":"Quiero exprime une volonté.","type":"choix","options":[{"id":"a","texte":"Le subjonctif remplace le futur dans les invitations"},{"id":"b","texte":"Vienes est une forme du subjonctif"},{"id":"c","texte":"Après quiero que, on emploie toujours l’infinitif"},{"id":"d","texte":"Après un verbe de volonté, on emploie le subjonctif"}],"multiple":false},{"enonce":"Complète avec le bon verbe.","aide":"Creer une opinion affirmée : quel mode ?","type":"trous","segments":["Creo que Pedro ",0," ir a la fiesta."],"banque":["pudiera","poder","pueda","puede"]}]}$ex$::jsonb,
