  ('1d154947-e80a-5112-8751-3821163edf36'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le journal de Marina","competence":"manier-langue","situation":"Marina a un examen la semaine prochaine. Elle écrit ce qu’elle veut, ce qu’elle craint et ce qu’elle espère.","documents":[{"id":"diario","type":"texte","genre":"lettre","titre":"El diario de Marina","blocs":["Querido diario:","Hoy quiero ir al cine, pero mi madre quiere que estudie más.","Dudo que el examen sea difícil. Creo que sé casi todo.","¡Ojalá apruebe!"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Pourquoi Marina écrit-elle « quiero ir » sans *que* ?","aide":"Qui veut ? Qui va au cinéma ?","type":"choix","options":[{"id":"a","texte":"Le subjonctif est interdit avec quiero"},{"id":"b","texte":"Parce que ir est un verbe irrégulier"},{"id":"c","texte":"Parce que la phrase est une question"},{"id":"d","texte":"Le sujet ne change pas : on garde l’infinitif"}],"multiple":false},{"enonce":"Touche les **trois verbes au subjonctif** du journal.","aide":"Ils suivent une volonté, un doute et un souhait.","type":"zone","document":"diario","multiple":true},{"enonce":"Range chaque début de phrase selon le mode qui suit.","aide":"Déclaration, perception, certitude : indicatif. Volonté, doute, jugement, certitude niée : subjonctif.","type":"categories","categories":[{"id":"c0","texte":"Indicatif"},{"id":"c1","texte":"Subjonctif"}],"items":[{"id":"i0","texte":"No creo que…"},{"id":"i1","texte":"Es necesario que…"},{"id":"i2","texte":"Creo que…"},{"id":"i3","texte":"Dudo que…"},{"id":"i4","texte":"Veo que…"},{"id":"i5","texte":"Es verdad que…"}]},{"enonce":"Remets en ordre : « Ma mère veut que j’étudie beaucoup. » La phrase commence par Mi.","aide":"Le verbe de volonté est suivi de que + subjonctif.","type":"ordre","items":[{"id":"a","texte":"Mi madre"},{"id":"b","texte":"quiere que"},{"id":"c","texte":"mucho"},{"id":"d","texte":"estudie"}]}]}$ex$::jsonb,
