   $ex${"titre":"Une lettre au courrier du cœur","competence":"argumenter","situation":"Nuria écrit à la rubrique de conseils de son magazine : sa meilleure amie ne lui parle plus. La rédaction lui répond.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Querida redacción","blocs":["Querida redacción: mi mejor amiga ya no me habla desde el lunes. No sé qué hacer. Ojalá pudiera arreglarlo."],"source":"Lettre écrite pour l’exercice"},{"id":"respuesta","type":"texte","genre":"lettre","titre":"Respuesta de la redacción","blocs":["Querida Nuria: yo que tú, hablaría hoy mismo con ella. Te aconsejo que hables con calma y sin enfadarte. ¿Y si le escribes una nota?","Y, sobre todo, no la llames cuando estés nerviosa."],"source":"Réponse écrite pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui exprime un **souhait improbable** (imparfait du subjonctif).","aide":"Ojalá + imparfait du subjonctif : « si seulement… ».","type":"zone","document":"carta","multiple":false},{"enonce":"Nuria écrit « ojalá pudiera ». Que laisse entendre cette forme ?","aide":"Compare avec « ojalá pueda », plus ouvert.","type":"choix","options":[{"id":"a","texte":"Qu’elle donne un ordre"},{"id":"b","texte":"Que le souhait est déjà réalisé"},{"id":"c","texte":"Qu’elle trouve le souhait peu réalisable"},{"id":"d","texte":"Que le souhait concerne le passé lointain"}],"multiple":false},{"enonce":"Touche le verbe à l’**impératif négatif**.","aide":"Il suit « no » et prend la forme du subjonctif présent.","type":"zone","document":"respuesta","multiple":false},{"enonce":"Complète avec le conditionnel pour dire « À ta place, je parlerais ».","aide":"Yo que tú se poursuit au conditionnel.","type":"trous","segments":["Yo que tú, ",0," con ella hoy mismo."],"banque":["hablo","hables","hablé","hablaría"]},{"enonce":"Remets en ordre : « Je te conseille que tu parles avec elle. » La phrase commence par Te aconsejo.","aide":"Après « te aconsejo que », le verbe est au subjonctif.","type"