   $ex${"titre":"Un après-midi au cinéma","competence":"comprendre-langue","situation":"Ana et Leo s’écrivent avant d’aller au cinéma. Leo a soif.","documents":[{"id":"cine","type":"dialogue","modele":"sms","titre":"Messages d’Ana et Leo","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Hola, Leo. Hoy voy al cine con unos amigos. ¿Vienes?"},{"qui":"Leo","texte":"Sí. Vuelvo del colegio a las seis. ¿Tienes agua fría?"},{"qui":"Ana","texte":"Sí, el agua está en mi mochila."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux contractions** des messages.","aide":"Elles sont formées de a + el et de de + el.","type":"zone","document":"cine","multiple":true},{"enonce":"Pourquoi Ana écrit-elle « el agua » et non « la agua » ?","aide":"Le nom reste féminin : regarde ce qui suit, « fría ».","type":"choix","options":[{"id":"a","texte":"Agua est féminin, mais a un a initial tonique"},{"id":"b","texte":"Agua est en réalité un nom masculin"},{"id":"c","texte":"Agua s’emploie toujours au pluriel"},{"id":"d","texte":"On met toujours el devant une boisson"}],"multiple":false},{"enonce":"Complète avec la contraction.","aide":"de + el se contractent toujours.","type":"trous","segments":["La casa ",0," profesor es grande."],"banque":["de el","del","al","a el"]}]}$ex$::jsonb,
