   $ex${"titre":"Se lo doy","competence":"analyser-document","situation":"Dans la classe, on s’exerce à remplacer des compléments par des pronoms. Il faut surveiller le cas du « se ».","documents":[{"id":"profe","type":"dialogue","modele":"sms","titre":"Questions de la professeure","participants":[{"nom":"Profesora","emoji":"👩‍🏫","cote":"gauche"},{"nom":"Alumno","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Profesora","texte":"¿Le das el libro a Juan?"},{"qui":"Alumno","texte":"Sí, se lo doy hoy."}],"source":"Messages écrits pour l’exercice"},{"id":"familia","type":"dialogue","modele":"sms","titre":"Messages de la famille","participants":[{"nom":"Madre","emoji":"👩","cote":"gauche"},{"nom":"Hijo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Madre","texte":"¿Les diste el regalo a tus primos?"},{"qui":"Hijo","texte":"Sí, se lo di ayer."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom qui remplace *le* quand il rencontre *lo*.","aide":"Il s’écrit en deux lettres, s…","type":"zone","document":"profe","multiple":false},{"enonce":"Complète avec le bon pronom.","aide":"Devant lo ou la, le COI change de forme.","type":"trous","segments":["Le doy el libro a Juan: ",0," lo doy. Les digo la verdad a mis padres: ",1," la digo."],"banque":["lo","se","les","le"]},{"enonce":"Remets en ordre : « Je vais le lui dire. » La phrase commence par Se.","aide":"COI puis COD, avant le verbe conjugué.","type":"ordre","items":[{"id":"a","texte":"a decir"},{"id":"b","texte":"voy"},{"id":"c","texte":"Se"},{"id":"d","texte":"lo"}]},{"enonce":"Range chaque forme selon la place du pronom.","aide":"Infinitif, gérondif et impératif affirmatif : soudé.","type":"categories","categories":[{"id":"c0","texte":"Pronom devant le verbe"},{"id":"c1","texte":"Pronom soudé derrière le verbe"}],"items":[{"id":"i0","texte":"Te lo digo"},{"id":"i1","texte":"Quiero dártelo"},{"id":"i2","texte":"No me lo des"},{"id":"i3","texte":"Dámelo"},{"id":"i4","texte":"Diciéndotelo"}]},{"enonce":"Dans le message du fils, à qui renvoie « se » dans « se lo di » ?","aide":"Regarde la question de la mère.","type":"choix","options":[{"id":"a","texte":"À ses cousins (COI pluriel)"},{"id":"b","texte":"À sa mère (celle qui demande)"},{"id":"c","texte":"Au cadeau (le COD)"},{"id":"d","texte":"À lui-même (réfléchi)"}],"multiple":false}]}$ex$::jsonb,
