  ('09443324-0712-5e5e-881c-d9fe7f73f382'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un lundi sans envie","competence":"comprendre-langue","situation":"Elena invite Hugo à sortir, mais Hugo n’a envie de rien. Ils s’écrivent des messages.","documents":[{"id":"parque","type":"dialogue","modele":"sms","titre":"Messages d’Elena et Hugo","participants":[{"nom":"Elena","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elena","texte":"¡Hola, Hugo! ¿Vienes al parque?"},{"qui":"Hugo","texte":"No, hoy no tengo ganas."},{"qui":"Elena","texte":"¿Quieres comer algo?"},{"qui":"Hugo","texte":"No quiero nada, gracias."},{"qui":"Elena","texte":"¿Ves a Pablo por la calle?"},{"qui":"Hugo","texte":"No veo a nadie desde mi ventana."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots négatifs** qui suivent le verbe dans les réponses de Hugo.","aide":"L’un veut dire « rien », l’autre « personne ».","type":"zone","document":"parque","multiple":true},{"enonce":"Remets en ordre : « Je ne veux rien manger. » La phrase commence par No.","aide":"Le no se place juste devant le verbe.","type":"ordre","items":[{"id":"a","texte":"quiero"},{"id":"b","texte":"nada"},{"id":"c","texte":"comer"},{"id":"d","texte":"No"}]},{"enonce":"Pourquoi Hugo écrit-il « No veo a nadie » et non « Veo a nadie » ?","aide":"Pense à la double négation espagnole.","type":"choix","options":[{"id":"a","texte":"Un mot négatif après le verbe exige no devant le verbe"},{"id":"b","texte":"No ne se met que devant un nom propre ou un prénom"},{"id":"c","texte":"Nadie ne peut s’employer qu’au début de la phrase"},{"id":"d","texte":"Veo a nadie est correct mais un peu moins poli"}],"multiple":false}]}$ex$::jsonb,
