   $ex${"titre":"Trois frères et sœurs","competence":"manier-langue","situation":"Lucía décrit sa famille dans une lettre. Un tableau donne l’âge, la taille et la note d’anglais de chacun.","documents":[{"id":"ficha","type":"tableau","titre":"Ficha de los hermanos","colonnes":["Nombre","Edad (años)","Altura (cm)","Nota de inglés"],"lignes":[["Pablo",16,175,7],["Ana",14,160,5],["Lucía",11,160,9]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"},{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Lucía","blocs":["Mi hermano Pablo es mayor que yo. Tengo mejor nota que Ana en inglés, aunque es más difícil de lo que parece.","Y Pablo crece cada vez más rápido: ¡ya es más alto que mi padre!"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux tailles** égales.","aide":"Compare la colonne « Altura ».","type":"zone","document":"ficha","multiple":true},{"enonce":"Complète avec le comparatif irrégulier.","aide":"Lucía a 11 ans, Pablo 16 ans.","type":"trous","segments":["Lucía es ",0," que Pablo."],"banque":["peor","mayor","menor","mejor"]},{"enonce":"Complète avec le comparatif irrégulier.","aide":"Compare 9 et 5. Et rappelle-toi : jamais « más mejor ».","type":"trous","segments":["Lucía tiene ",0," nota que Ana en inglés."],"banque":["más mejor","mayor","mejor","peor"]},{"enonce":"Pourquoi Lucía écrit-elle « más difícil de lo que parece » ?","aide":"Regarde ce qui vient après le comparatif : un verbe conjugué.","type":"choix","options":[{"id":"a","texte":"Difícil est un comparatif irrégulier"},{"id":"b","texte":"Elle compare deux personnes"},{"id":"c","texte":"Il y a un nombre après más"},{"id":"d","texte":"Le second terme est une proposition"}],"multiple":false},{"enonce":"Remets en ordre : « Ana est plus jeune que Pablo. » La phrase commence par Ana.","aide":"*Menor que* se construit comme *más… que*.","type":"ordre","items":[{"id":"a","texte":"menor"},{"id":"b","texte":"que"},{"id":"c","texte":"es"},{"id":"d","texte