   $ex${"titre":"Un sac oublié","competence":"comprendre-langue","situation":"Leo trouve un sac dans la classe et demande à Ana s’il est à elle.","documents":[{"id":"mochila","type":"dialogue","modele":"sms","titre":"Messages de Leo et Ana","participants":[{"nom":"Leo","emoji":"👦","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leo","texte":"¿Es tu mochila, Ana?"},{"qui":"Ana","texte":"No, no es mía. Mi mochila es azul y mis libros están dentro."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois possessifs** placés devant un nom.","aide":"Ils s’accordent avec ce qui est possédé.","type":"zone","document":"mochila","multiple":true},{"enonce":"Complète avec le bon possessif.","aide":"Après le verbe ser, on emploie la forme tonique.","type":"trous","segments":["Ese cuaderno es de Ana: es ",0,"."],"banque":["suya","suyo","su","sus"]},{"enonce":"Associe chaque possessif à sa traduction.","aide":"Le possessif s’accorde avec la chose possédée.","type":"association","gauche":[{"id":"g0","texte":"mi libro"},{"id":"g1","texte":"mis libros"},{"id":"g2","texte":"tu casa"},{"id":"g3","texte":"nuestra casa"}],"droite":[{"id":"d0","texte":"mon livre"},{"id":"d1","texte":"notre maison"},{"id":"d2","texte":"ta maison"},{"id":"d3","texte":"mes livres"}]}]}$ex$::jsonb,
