   $ex${"titre":"Quand je rentre à la maison","competence":"manier-langue","situation":"Une élève raconte son retour à la maison. En espagnol, ce n’est pas le possessif qu’on emploie pour le corps et les vêtements.","documents":[{"id":"tarde","type":"texte","genre":"recit","titre":"Mi tarde","blocs":["Cuando llego a casa, me quito el abrigo y me lavo las manos.","Después me siento y me duele la cabeza: ¡hoy hubo mucho ruido en clase!"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Pourquoi écrit-on « me lavo las manos » et non « me lavo mis manos » ?","aide":"Qui se lave ? Le pronom me le dit.","type":"choix","options":[{"id":"a","texte":"Manos est un nom masculin"},{"id":"b","texte":"Manos est un nom au singulier"},{"id":"c","texte":"Me indique déjà à qui sont les mains"},{"id":"d","texte":"Mis ne s’emploie jamais avec lavar"}],"multiple":false},{"enonce":"Touche les **trois articles** qui remplacent « mon, mes, ma » en français.","aide":"Ils précèdent abrigo, manos et cabeza.","type":"zone","document":"tarde","multiple":true},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"Dans ces trois phrases, aucun possessif.","type":"association","gauche":[{"id":"g0","texte":"Je me lave les mains"},{"id":"g1","texte":"Il a mal à la tête"},{"id":"g2","texte":"Il enleva son manteau"}],"droite":[{"id":"d0","texte":"Le duele la cabeza"},{"id":"d1","texte":"Se quitó el abrigo"},{"id":"d2","texte":"Me lavo las manos"}]},{"enonce":"Remets en ordre : « Il a mal à la tête. » La phrase commence par Le.","aide":"Le COI précède le verbe.","type":"ordre","items":[{"id":"a","texte":"duele"},{"id":"b","texte":"cabeza"},{"id":"c","texte":"Le"},{"id":"d","texte":"la"}]}]}$ex$::jsonb,
