   $ex${"titre":"Objets trouvés","competence":"analyser-document","situation":"Marina a trouvé un manteau et un sac en classe. Elle demande à qui ils appartiennent, et Pablo répond avec des possessifs.","documents":[{"id":"perdidos","type":"dialogue","modele":"sms","titre":"Messages de Marina et Pablo","participants":[{"nom":"Marina","emoji":"👩","cote":"gauche"},{"nom":"Pablo","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Marina","texte":"He encontrado un abrigo y una mochila en clase. ¿De quién son?"},{"qui":"Pablo","texte":"El abrigo es mío. Pero esa mochila no es mía."},{"qui":"Marina","texte":"Entonces es de Ana: es suya. Su casa está cerca, ¿verdad?"}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois possessifs toniques** employés après le verbe *ser*.","aide":"Ils ne sont pas devant un nom.","type":"zone","document":"perdidos","multiple":true},{"enonce":"Complète avec le possessif.","aide":"Le pronom reprend « la casa » : féminin singulier.","type":"trous","segments":["Nuestra casa es pequeña, pero la de Ana es grande: la ",0," es muy grande."],"banque":["sus","suya","suyo","su"]},{"enonce":"Dans « Su casa está cerca », comment préciser que c’est la maison d’Ana ?","aide":"*Su* peut être « son, sa, leur, votre » : on précise avec *de*.","type":"choix","options":[{"id":"a","texte":"la casa de él"},{"id":"b","texte":"la casa de usted"},{"id":"c","texte":"la casa de ella"},{"id":"d","texte":"la casa de ellos"}],"multiple":false},{"enonce":"Remets en ordre : « Mon fils, viens ici ! » La phrase commence par ¡Hijo.","aide":"Au vocatif, le possessif tonique suit le nom.","type":"ordre","items":[{"id":"a","texte":"aquí!"},{"id":"b","texte":"ven"},{"id":"c","texte":"mío,"},{"id":"d","texte":"¡Hijo"}]},{"enonce":"Range chaque groupe selon la place du possessif.","aide":"Devant le nom : mi, tu, su. Après le nom : mío, tuyo, suyo.","type":"categories","categories":[{"id":"c0","texte":"Atone (devant le nom)"},{"id":"c1","texte":"Tonique (après le nom)"}],"items":[{"id":"i0","texte":"una casa nuestra"},{"id":"i1","texte":"un amigo tuyo"},{"id":"i2","texte":"mi libro"},{"id":"i3","texte":"tus amigos"},{"id":"i4","texte":"un libro mío"},{"id":"i5","texte":"nuestra casa"}]}]}$ex$::jsonb,
