   $ex${"titre":"Un sábado sans plan","competence":"comprendre-langue","situation":"Pablo et Lucía cherchent quoi faire samedi. Ils n’ont encore rien prévu.","documents":[{"id":"plan","type":"dialogue","modele":"sms","titre":"Mensajes de Pablo y Lucía","participants":[{"nom":"Pablo","emoji":"👦","cote":"gauche"},{"nom":"Lucía","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Pablo","texte":"Hola, Lucía. ¿Tienes algún plan para el sábado?"},{"qui":"Lucía","texte":"No tengo ningún plan. ¿Y tú?"},{"qui":"Pablo","texte":"Yo tampoco. ¿Vamos a algún sitio?"},{"qui":"Lucía","texte":"Vamos al parque. Cada sábado hay mercado allí."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois indéfinis apocopés** (raccourcis) de la conversation.","aide":"Ils sont devant un nom masculin singulier : cherche algún et ningún.","type":"zone","document":"plan","multiple":true},{"enonce":"Dans « Cada sábado », que peut-on dire de *cada* ?","aide":"Regarde si le mot change quand on parle de plusieurs jours : *cada día*, *cada dos horas*.","type":"choix","options":[{"id":"a","texte":"Oui, il prend un s si on parle de plusieurs jours"},{"id":"b","texte":"Il s’accorde avec le genre du nom"},{"id":"c","texte":"Non, cada est toujours invariable"},{"id":"d","texte":"Oui, il devient cadas au pluriel"}],"multiple":false},{"enonce":"Complète avec le bon indéfini.","aide":"Il s’agit d’une personne, et la phrase est négative.","type":"trous","segments":["Al llegar al parque, Pablo dice : « No veo a ",0,". ¡Está vacío! »"],"banque":["nada","algo","nadie","alguna"]}]}$ex$::jsonb,
