   $ex${"titre":"Le club de théâtre du collège","competence":"manier-langue","situation":"Le collège affiche une annonce pour recruter de nouveaux élèves dans son club de théâtre.","documents":[{"id":"club","type":"fiche","modele":"affiche","entete":"Club de teatro","sousTitre":"Instituto Cervantes · aula 12","emoji":"🎭","lignes":[{"texte":"Cualquier alumno puede venir.","id":"z1"},{"texte":"Cada martes, a las cinco.","id":"z2"},{"texte":"No hace falta ninguna experiencia.","id":"z3"},{"texte":"Trae algún objeto para la escena.","id":"z4"}],"pied":"¡Te esperamos!","teinte":"violet","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche la ligne qui contient un indéfini à la **forme féminine**.","aide":"Cherche un indéfini terminé par -a, pas apocopé.","type":"zone","document":"club","multiple":false},{"enonce":"Complète avec la forme correcte.","aide":"*Duda* est un nom féminin.","type":"trous","segments":["No tengo ",0," duda sobre la fecha."],"banque":["nadie","ninguna","ninguno","ningún"]},{"enonce":"Pourquoi l’affiche dit-elle « cualquier alumno » et non « cualquiera alumno » ?","aide":"Regarde ce qui suit le mot : un nom, ou rien ?","type":"choix","options":[{"id":"a","texte":"Cualquiera est réservé aux personnes"},{"id":"b","texte":"Cualquiera s’apocope devant un nom"},{"id":"c","texte":"Cualquiera ne s’emploie jamais au singulier"},{"id":"d","texte":"Alumno est un nom féminin singulier"}],"multiple":false},{"enonce":"Associe chaque phrase française à sa traduction.","aide":"Pense à la paire positif / négatif pour les personnes et les choses.","type":"association","gauche":[{"id":"g0","texte":"Je ne vois personne"},{"id":"g1","texte":"Tu veux quelque chose ?"},{"id":"g2","texte":"Chaque jour"},{"id":"g3","texte":"Tous les deux"}],"droite":[{"id":"d0","texte":"Ambos"},{"id":"d1","texte":"Cada día"},{"id":"d2","texte":"¿Quieres algo?"},{"id":"d3","texte":"No veo a nadie"}]}]}$ex$::jsonb,
