   $ex${"titre":"Les copies de la classe","competence":"analyser-document","situation":"Le professeur d’espagnol corrige des phrases d’élèves. Certaines contiennent une faute sur un indéfini.","documents":[{"id":"copias","type":"tableau","titre":"Las frases de los alumnos","colonnes":["Alumno","Frase"],"lignes":[["Marta","Estudio todos días en la biblioteca."],["Iván","Quiero otro libro, por favor."],["Sara","Cualquiera día puedo venir."],["Hugo","No tengo ningún problema."],["Nora","Mi tío tiene un otro coche."]],"enteteLignes":true,"source":"Phrases écrites pour l’exercice"},{"id":"primos","type":"dialogue","modele":"sms","titre":"Mensajes de Elena y Dani","participants":[{"nom":"Elena","emoji":"👧","cote":"gauche"},{"nom":"Dani","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elena","texte":"Mis dos primos vienen mañana. Ambos viven en Sevilla."},{"qui":"Dani","texte":"¿Y los demás? ¿Viene también tu tía?"},{"qui":"Elena","texte":"No, los demás se quedan en casa. Cada uno tiene sus planes."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **trois phrases** qui contiennent une faute.","aide":"Une faute d’article, une faute d’apocope, et un article de trop.","type":"zone","document":"copias","multiple":true},{"enonce":"Comment corriger « Estudio todos días » ?","aide":"Todo exige l’article : *todo el día*, *toda la noche*.","type":"choix","options":[{"id":"a","texte":"Supprimer todos : estudio días"},{"id":"b","texte":"Mettre todos au féminin : todas días"},{"id":"c","texte":"Mettre días au singulier : todos día"},{"id":"d","texte":"Ajouter l’article : todos los días"}],"multiple":false},{"enonce":"Complète avec le bon mot.","aide":"Le message parle de deux personnes, et on veut dire « tous les deux ».","type":"trous","segments":["Mis dos primos vienen : ",0," viven en Sevilla."],"banque":["cada","ninguno","demás","ambos"]},{"enonce":"Dans « los demás se quedan en casa », que désigne *los demás* ?","aide":"Elena vient de parler de deux cousins, puis d’autres personnes.","type":"choix","options":[{"id":"a","texte":"Les autres, le reste des personnes"},{"id":"b","texte":"Aucun des cousins"},{"id":"c","texte":"Tous les cousins sans exception"},{"id":"d","texte":"Les deux cousins seulement"}],"multiple":false},{"enonce":"Remets en ordre : « Chacun a ses projets. » La phrase commence par Cada.","aide":"*Cada uno* = chacun.","type":"ordre","items":[{"id":"a","texte":"sus"},{"id":"b","texte":"planes"},{"id":"c","texte":"Cada"},{"id":"d","texte":"tiene"},{"id":"e","texte":"uno"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r2c1","r4c1"]},"explication":"**Todos días** (il faut *todos los días*), **Cualquiera día** (il faut *cualquier día*) et **un otro coche** (il faut *otro coche*, sans article indéfini)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Todos los días** : *todo* s’accorde et exige l’article défini."},{"cle":{"type":"trous","trous":[["ambos"]]},"affichage":"ambos","explication":"**Ambos** : « tous les deux »."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Los demás** = les autres, le reste (ici la tante et les autres membres de la famille)."},{"cle":{"type":"ordre","ids":["c","e","d","a","b"]},"explication":"**Cada uno tiene sus planes** : *cada uno* est le sujet, suivi du verbe."}]$ex$::jsonb),
