   $ex${"titre":"La rutina de Nora","competence":"comprendre-langue","situation":"Nora raconte son réveil du matin. Son frère, lui, ne fait pas du tout la même chose.","documents":[{"id":"rutina","type":"texte","genre":"recit","titre":"Mi mañana","blocs":["Me levanto a las siete. Me ducho y me visto en cinco minutos.","Mi hermano, en cambio, se despierta tarde y se queja de todo."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois pronoms réfléchis** de Nora (« yo »).","aide":"Ils précèdent levanto, ducho et visto.","type":"zone","document":"rutina","multiple":true},{"enonce":"Complète avec le bon pronom.","aide":"Le sujet est « mi hermano » : 3e personne.","type":"trous","segments":["Mi hermano ",0," despierta tarde."],"banque":["te","se","nos","me"]},{"enonce":"Complète avec le verbe et son pronom.","aide":"Avec un infinitif, le pronom se soude derrière. Le sujet est *yo* (« quiero »).","type":"trous","segments":["Los sábados quiero ",0," más tarde."],"banque":["levantarme","me levantar","levantarse","levantarte"]},{"enonce":"Que signifie « se queja » ?","aide":"*Quejarse* est un verbe essentiellement pronominal.","type":"choix","options":[{"id":"a","texte":"Il se lave"},{"id":"b","texte":"Il se plaint"},{"id":"c","texte":"Il se réveille"},{"id":"d","texte":"Il s’endort"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m5","m8"]},"explication":"**Me levanto, me ducho, me visto** : le pronom *me* correspond au sujet *yo* et se place devant le verbe conjugué."},{"cle":{"type":"trous","trous":[["se"]]},"affichage":"se","explication":"**Se despierta** : le pronom s’accorde avec le sujet."},{"cle":{"type":"trous","trous":[["levantarme"]]},"affichage":"levantarme","explication":"**Levantarme** : à l’infinitif le pronom est soudé derrière et s’accorde avec le sujet (*quiero* → *me*)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Quejarse** = se plaindre : le pronom fait partie du verbe."}]$ex$::jsonb),
  ('0be4629e-2624-5a27-9f8d-8e6876100948'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le tableau d’annonces","competence":"manier-langue","situation":"Dans le hall d’un centre culturel, plusieurs annonces utilisent le pronom *se*.","documents":[{"id":"tablon","type":"fiche","modele":"panneau","entete":"Tablón de anuncios","sousTitre":"Centro cultural · entrada","emoji":"📌","lignes":[{"texte":"Se venden bicis de segunda mano","id":"z1"},{"texte":"Aquí se come muy bien","id":"z2"},{"texte":"Se buscan voluntarios para la feria","id":"z3"},{"texte":"Se alquila un piso pequeño","id":"z4"}],"teinte":"jaune","source":"Annonces écrites pour l’exercice"}],"questions":[{"enonce":"Touche les **deux annonces** où le verbe est au **pluriel** parce qu’il s’accorde avec son sujet.","aide":"Cherche venden et buscan.","type":"zone","document":"tablon","multiple":true},{"enonce":"Complète avec la bonne forme.","aide":"Le sujet est « pisos » (pluriel).","type":"trous","segments":["Se ",0," pisos baratos en el barrio."],"banque":["vendo","vender","vende","venden"]},{"enonce":"Dans « Aquí se come muy bien », quelle est la valeur de *se* ?","aide":"Personne n’est désigné : on parle de tout le monde.","type":"choix","options":[{"id":"a","texte":"Lexicale : comerse est toujours pronominal"},{"id":"b","texte":"Impersonnelle : « on mange bien ici »"},{"id":"c","texte":"Réfléchie : quelqu’un se mange lui-même"},{"id":"d","texte":"Réciproque : deux personnes se mangent"}],"multiple":false},{"enonce":"Associe chaque phrase espagnole à son sens.","aide":"Quatre valeurs : passive, impersonnelle, réciproque, réfléchie.","type":"association","gauche":[{"id":"g0","texte":"Se venden pisos"},{"id":"g1","texte":"Se dice que…"},{"id":"g2","texte":"Se escriben"},{"id":"g3","texte":"Se lava"}],"droite":[{"id":"d0","texte":"On dit que…"},{"id":"d1","texte":"Ils s’écrivent l’un à l’autre"},{"id":"d2","texte":"Il se lave lui-même"},{"id":"d3","texte":"Des appartements sont à vendre"}]}]}$ex$::jsonb,
