   $ex${"titre":"Une nuit au village","competence":"analyser-texte","situation":"Une élève de 3e rédige un récit : elle rentre un soir au village et entend un bruit. Un tableau rappelle l’imparfait de quatre verbes.","documents":[{"id":"noche","type":"texte","genre":"recit","titre":"Una noche en el pueblo","blocs":["Era de noche y hacía frío. Yo volvía a casa cuando, de repente, oí un ruido.","Mi vecina miraba por la ventana, pero no me dijo nada. Entonces corrí hasta la puerta."],"source":"Récit écrit pour l’exercice"},{"id":"imp","type":"tableau","titre":"Imperfecto","colonnes":["Verbo","yo","nosotros"],"lignes":[["ser","era","?"],["ir","iba","?"],["ver","veía","?"],["hablar","hablaba","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois verbes à l’imparfait** qui décrivent le décor.","aide":"Ils ne font pas avancer l’histoire : ils décrivent ce qui est en cours.","type":"zone","document":"noche","multiple":true},{"enonce":"Dans « volvía a casa cuando oí un ruido », quel verbe fait avancer l’action ?","aide":"Le bruit interrompt l’action en cours.","type":"choix","options":[{"id":"a","texte":"volvía (imparfait)"},{"id":"b","texte":"les deux de la même façon"},{"id":"c","texte":"oí (passé simple)"},{"id":"d","texte":"aucun des deux"}],"multiple":false},{"enonce":"Complète le tableau avec l’imparfait à la forme nosotros.","aide":"Ser, ir et ver sont irréguliers ; hablar prend -ábamos.","type":"trous","segments":["ser → ",0," ; ir → ",1," ; ver → ",2," ; hablar → ",3],"banque":["íbamos","veíamos","éramos","hablábamos","serían","vimos"]},{"enonce":"Associe chaque infinitif à sa forme ellos à l’imparfait.","aide":"Vivir est régulier en -ía ; les trois autres sont les irréguliers.","type":"association","gauche":[{"id":"g0","texte":"vivir"},{"id":"g1","texte":"ser"},{"id":"g2","texte":"ir"},{"id":"g3","texte":"ver"}],"droite":[{"id":"d0","texte":"eran"},{"id":"d1","texte":"iban"},{"id":"d2","texte":"veían"},{"id":"d3","texte":"vivían"}]},{"enonce":"Remets en ordre : « Je rentrais chez moi quand il pleuvait. » La phrase commence par Volvía.","aide":"L’imparfait « volvía » est suivi du lieu, puis de la subordonnée.","type":"ordre","items":[{"id":"a","texte":"a casa"},{"id":"b","texte":"llovía"},{"id":"c","texte":"cuando"},{"id":"d","texte":"Volvía"}]}]}$ex$::jsonb,
