  ('193f6816-fc53-5451-bae3-f2597571a846'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Avant l’arrivée des grands-parents","competence":"comprendre-langue","situation":"Lucas doit ranger sa chambre avant l’arrivée de ses grands-parents. Sa mère lui écrit.","documents":[{"id":"abuelos","type":"dialogue","modele":"sms","titre":"Messages de Mamá et de Lucas","participants":[{"nom":"Mamá","emoji":"👩","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mamá","texte":"Quiero que ordenes tu cuarto antes de que lleguen los abuelos."},{"qui":"Lucas","texte":"Vale, mamá. Cuando termine los deberes, lo hago."},{"qui":"Mamá","texte":"Hazlo ya, para que puedas ver la tele después."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **quatre verbes au subjonctif présent**.","aide":"Ils suivent « que », « antes de que », « cuando » ou « para que ».","type":"zone","document":"abuelos","multiple":true},{"enonce":"Pourquoi Lucas écrit-il « cuando termine » et non « cuando terminaré » ?","aide":"Le français dit « quand je finirai » : l’espagnol fait autrement.","type":"choix","options":[{"id":"a","texte":"Parce que la phrase est négative, donc au subjonctif"},{"id":"b","texte":"Parce que le futur n’existe pas en espagnol"},{"id":"c","texte":"Parce que terminar est un verbe irrégulier"},{"id":"d","texte":"Après cuando à valeur de futur, on met le subjonctif"}],"multiple":false},{"enonce":"Complète avec le subjonctif de ordenar à la forme tú.","aide":"Verbe en -ar : le subjonctif prend les terminaisons en -e.","type":"trous","segments":["Quiero que tú ",0," tu cuarto."],"banque":["ordenas","ordenes","ordena","ordenarás"]}]}$ex$::jsonb,
