   $ex${"titre":"Une invitation à Madrid","competence":"manier-langue","situation":"Elena invite son amie Julia à venir la voir à Madrid. Elle lui écrit ses souhaits et ce qu’il faut préparer.","documents":[{"id":"julia","type":"texte","genre":"lettre","titre":"Querida Julia","blocs":["Querida Julia: el año que viene quiero que vengas a Madrid. Es necesario que tengas el pasaporte listo y que sepas cuándo sale el tren.","Espero que estés contenta con el plan. Ojalá haga buen tiempo y que no llueva mucho."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux subjonctifs irréguliers** qui ne viennent pas de la forme « yo ».","aide":"Ce sont les verbes saber et estar : leur « yo » ne se termine pas par -o.","type":"zone","document":"julia","multiple":true},{"enonce":"Associe chaque infinitif à son subjonctif présent à la 1re personne.","aide":"Pour tener et hacer, pars de « yo tengo » et « yo hago ».","type":"association","gauche":[{"id":"g0","texte":"tener"},{"id":"g1","texte":"hacer"},{"id":"g2","texte":"saber"},{"id":"g3","texte":"ir"}],"droite":[{"id":"d0","texte":"sepa"},{"id":"d1","texte":"vaya"},{"id":"d2","texte":"tenga"},{"id":"d3","texte":"haga"}]},{"enonce":"Complète avec le subjonctif de salir à la forme nosotros.","aide":"Salir : yo salgo, donc le radical du subjonctif est salg-.","type":"trous","segments":["Es necesario que nosotros ",0," temprano."],"banque":["salgamos","salimos","saldremos","salamos"]},{"enonce":"Pourquoi dit-on « que tengas » et non « que tenas » ?","aide":"Regarde la 1re personne du présent de tener.","type":"choix","options":[{"id":"a","texte":"Parce que tener est un verbe régulier"},{"id":"b","texte":"Parce que le subjonctif part de « yo tengo »"},{"id":"c","texte":"Parce que tener est un verbe en -ar"},{"id":"d","texte":"Parce que la phrase est au passé simple"}],"multiple":false}]}$ex$::jsonb,
