   $ex${"titre":"Deux entradas para el sábado","competence":"manier-langue","situation":"Sara et Marcos organisent une sortie au cinéma. Une affiche donne le programme.","documents":[{"id":"cine","type":"dialogue","modele":"sms","titre":"Mensajes de Sara y Marcos","participants":[{"nom":"Marcos","emoji":"👦","cote":"gauche"},{"nom":"Sara","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Marcos","texte":"Me gusta mucho el cine. Me encantan las películas de aventuras."},{"qui":"Sara","texte":"A mí también me gusta el cine, pero no me gusta nada el fútbol."},{"qui":"Marcos","texte":"A mí tampoco. Prefiero el baloncesto."},{"qui":"Sara","texte":"Me hacen falta dos entradas para el sábado."}],"source":"Messages écrits pour l’exercice"},{"id":"cartelera","type":"fiche","modele":"affiche","entete":"Cine Goya","sousTitre":"Cartelera del sábado","emoji":"🎬","lignes":[{"texte":"Aventuras en la selva"},{"texte":"Sábado, a las 18:00"},{"texte":"Entrada : 6 euros"}],"teinte":"ambre","source":"Affiche écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui exprime l’**accord après une phrase négative**.","aide":"Marcos dit « moi non plus ».","type":"zone","document":"cine","multiple":false},{"enonce":"Pourquoi Sara dit-elle « A mí también » en réponse à Marcos ?","aide":"Compare avec « A mí tampoco » dit après la négation de Sara.","type":"choix","options":[{"id":"a","texte":"Sara est en désaccord avec Marcos"},{"id":"b","texte":"Elle répond à une question de Marcos"},{"id":"c","texte":"Marcos vient d’affirmer quelque chose"},{"id":"d","texte":"Marcos vient de dire une négation"}],"multiple":false},{"enonce":"Complète avec le bon mot.","aide":"*Hacer falta* = être nécessaire.","type":"trous","segments":["Me hacen ",0," dos entradas."],"banque":["gusta","duele","faltan","falta"]},{"enonce":"Complète avec le bon mot.","aide":"On veut dire « pas du tout ».","type":"trous","segments":["No me gusta ",0," el fútbol."],"banque":["mucho","nada","muy","nadie"]},{"enonce":"Remets en ordre : « Il me reste peu d’argent. » La phrase commence par Me.","aide":"*Quedar* se construit comme *gustar*.","type":"ordre","items":[{"id":"a","texte":"dinero"},{"id":"b","texte":"queda"},{"id":"c","texte":"Me"},{"id":"d","texte":"poco"}]},{"enonce":"Sara et Marcos achètent deux entrées. Combien paient-ils en tout ?","aide":"Regarde le prix d’une entrée sur l’affiche.","type":"nombre","unite":"€"}]}$ex$::jsonb,
