  ('75e01212-05cc-5d16-b5ff-0978f4237166'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le règlement du camp d’été","competence":"comprendre-langue","situation":"Marta est monitrice dans un camp d’été à Ávila. Elle écrit à Pablo, un nouvel arrivé, pour lui dire ce qu’il faut faire demain.","documents":[{"id":"camp","type":"dialogue","modele":"sms","titre":"Messages de Marta et de Pablo","participants":[{"nom":"Marta","emoji":"👩","cote":"gauche"},{"nom":"Pablo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"Hola, Pablo. Mañana hay que levantarse a las siete."},{"qui":"Pablo","texte":"Vale. Yo tengo que llamar a mi madre antes del desayuno."},{"qui":"Marta","texte":"Perfecto. Y hay que llevar gorra: hace mucho sol."},{"qui":"Pablo","texte":"Entonces tengo que buscar mi gorra esta noche."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les **deux expressions** qui disent une règle valable pour tout le monde.","aide":"Cherche l’expression qui n’a pas de sujet : elle ne parle de personne en particulier.","type":"zone","document":"camp","multiple":true},{"enonce":"Que dit Pablo avec « tengo que llamar a mi madre » ?","aide":"Regarde le sujet de la phrase : « yo ».","type":"choix","options":[{"id":"a","texte":"Qu’il a le droit d’appeler sa mère"},{"id":"b","texte":"Que lui seul doit appeler sa mère"},{"id":"c","texte":"Qu’il a déjà appelé sa mère"},{"id":"d","texte":"Que tout le monde doit appeler sa mère"}],"multiple":false},{"enonce":"Complète la règle impersonnelle, sans sujet.","aide":"Une règle pour tous ne désigne personne : quelle tournure n’a pas de sujet ?","type":"trous","segments":["Regla del campamento: ",0," respetar el silencio por la noche."],"banque":["tenemos que","tengo que","tienes que","hay que"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m4","m22","m23"]},"explication":"**Hay que** exprime une obligation impersonnelle, valable pour tous : elle n’a pas de sujet."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Tengo que** + infinitif exprime l’obligation personnelle : c’est Pablo qui doit agir."},{"cle":{"type":"trous","trous":[["hay que"]]},"affichage":"hay que","explication":"**Hay que respetar el silencio** : hay que est invariable et vaut pour tout le monde."}]$ex$::jsonb),
  ('75e01212-05cc-5d16-b5ff-0978f4237166'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le courriel de la directrice","competence":"manier-langue","situation":"La directrice du collège de Ségovie écrit aux parents avant une sortie. Dans son message, certaines obligations visent tout le monde et d’autres une seule personne.","documents":[{"id":"correo","type":"texte","genre":"lettre","titre":"Excursión a Segovia","blocs":["Asunto: excursión del jueves","Queridos padres: el jueves vamos de excursión. Los alumnos tienen que llevar un bocadillo y agua. Además, hay que salir del colegio a las ocho en punto.","Pablo tiene que traer también la autorización firmada, porque ayer se olvidó. Muchas gracias por su ayuda."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’expression qui exprime une obligation **impersonnelle**.","aide":"Elle n’a pas de sujet et vaut pour tout le groupe.","type":"zone","document":"correo","multiple":true},{"enonce":"Complète avec la tournure qui s’accorde avec le sujet.","aide":"Le sujet est « los alumnos » : il faut une forme conjuguée à la 3e personne du pluriel.","type":"trous","segments":["Los alumnos ",0," llevar un bocadillo."],"banque":["tengo que","tienen que","hay que","tiene que"]},{"enonce":"Remets en ordre : « Il faut partir à huit heures. » La phrase commence par Hay.","aide":"Hay que + infinitif, puis le complément de temps.","type":"ordre","items":[{"id":"a","texte":"ocho"},{"id":"b","texte":"a"},{"id":"c","texte":"que"},{"id":"d","texte":"Hay"},{"id":"e","texte":"las"},{"id":"f","texte":"salir"}]},{"enonce":"Pourquoi la directrice écrit-elle « Pablo tiene que traer… » plutôt que « hay que traer… » ?","aide":"Se demande-t-on quelque chose à tout le monde ou à une seule personne ?","type":"choix","options":[{"id":"a","texte":"Tiene que est plus poli que hay que"},{"id":"b","texte":"L’obligation ne vise que Pablo"},{"id":"c","texte":"Pablo est le directeur du collège"},{"id":"d","texte":"Hay que ne s’emploie qu’au pluriel"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21","m22"]},"explication":"**Hay que salir** : l’obligation vaut pour tous, sans sujet précis."},{"cle":{"type":"trous","trous":[["tienen que"]]},"affichage":"tienen que","explication":"**Los alumnos tienen que** : tener que se conjugue avec son sujet. Hay que, lui, ne s’emploie jamais avec un sujet."},{"cle":{"type":"ordre","ids":["d","c","f","b","e","a"]},"explication":"**Hay que salir a las ocho** : hay que est suivi directement de l’infinitif."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Tiene que** désigne une personne ; hay que est réservé aux règles générales."}]$ex$::jsonb),
  ('75e01212-05cc-5d16-b5ff-0978f4237166'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le journal de Sofía","competence":"manier-langue","situation":"Sofía tient un journal. Elle y note ce qu’elle a dû faire, ce qu’elle devait faire dans son village et ce qu’il faut faire pour la rentrée. Une deuxième fiche classe quatre phrases de la semaine.","documents":[{"id":"diario","type":"texte","genre":"recit","titre":"Diario de Sofía","blocs":["Ayer tuve que levantarme a las seis para ir al médico.","Cuando vivía en el pueblo, tenía que ayudar a mi abuela cada mañana.","Hoy hay que pagar la matrícula del instituto y mañana habrá que comprar los libros."],"source":"Journal écrit pour l’exercice"},{"id":"frases","type":"tableau","titre":"Frases de la semana","colonnes":["N.º","Frase"],"lignes":[["1","Hay que ser puntual"],["2","Tuve que repetir el examen"],["3","Debes respetar a los mayores"],["4","Debe de estar enfermo"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux expressions** impersonnelles du journal.","aide":"Elles ne portent pas de sujet : l’une est au présent, l’autre au futur.","type":"zone","document":"diario","multiple":true},{"enonce":"Dans « tenía que ayudar a mi abuela », que sait-on de ce que Sofía a fait ?","aide":"Compare avec « tuve que levantarme » du premier paragraphe.","type":"choix","options":[{"id":"a","texte":"Sofía a refusé de faire ce qu’on lui demandait"},{"id":"b","texte":"Sofía a obéi, l’obligation a été exécutée une fois"},{"id":"c","texte":"L’obligation existait ; on ne sait pas si elle a été suivie"},{"id":"d","texte":"C’est une règle générale valable pour tout le monde"}],"multiple":false},{"enonce":"Dans le tableau, touche la phrase qui exprime une **probabilité**.","aide":"Une seule tournure avec deber veut dire « il doit être » sans obligation.","type":"zone","document":"frases","multiple":false},{"enonce":"Associe chaque phrase du tableau à son idée.","aide":"Hay que n’a pas de sujet ; deber sans « de » exprime le devoir.","type":"association","gauche":[{"id":"g0","texte":"Hay que ser puntual"},{"id":"g1","texte":"Tuve que repetir el examen"},{"id":"g2","texte":"Debes respetar a los mayores"},{"id":"g3","texte":"Debe de estar enfermo"}],"droite":[{"id":"d0","texte":"supposition"},{"id":"d1","texte":"obligation exécutée"},{"id":"d2","texte":"règle pour tous"},{"id":"d3","texte":"devoir moral"}]},{"enonce":"Complète avec la tournure qui dit que l’obligation a été **exécutée**.","aide":"Le passé simple conclut ; l’imparfait laisse ouvert.","type":"trous","segments":["Ayer ",0," estudiar toda la tarde, y por fin aprobé el examen."],"banque":["tenía que","tuve que","hay que","debe de"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m26","m34","m35"]},"explication":"**Hay que** et **habrá que** : la même tournure impersonnelle, au présent puis au futur."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’imparfait **tenía que** laisse la question ouverte ; le passé simple *tuve que* conclut : l’obligation a été exécutée."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**Debe de estar enfermo** : deber de + infinitif exprime la supposition (il doit être malade)."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"*Hay que* = règle générale ; *tuve que* = obligation accomplie ; *debes* = devoir moral ; *debe de* = supposition."},{"cle":{"type":"trous","trous":[["tuve que"]]},"affichage":"tuve que","explication":"**Tuve que estudiar** : le passé simple dit que l’obligation a été exécutée."}]$ex$::jsonb),
