   $ex${"titre":"Tu ou usted ?","competence":"comprendre-langue","situation":"Ana, une collégienne, rencontre le directeur d’un collège espagnol. Elle doit choisir la bonne façon de parler.","documents":[{"id":"director","type":"dialogue","modele":"sms","titre":"Conversation avec le directeur","participants":[{"nom":"Ana","emoji":"👧","cote":"gauche"},{"nom":"Director","emoji":"👨","cote":"droite"}],"repliques":[{"qui":"Ana","texte":"Buenos días, señor. ¿Usted habla francés?"},{"qui":"Director","texte":"Sí, un poco. ¿Y tú, de dónde eres?"},{"qui":"Ana","texte":"Soy de Lyon, señor."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom de **politesse** qu’Ana emploie pour s’adresser au directeur.","aide":"C’est le mot qu’on traduit par « vous ».","type":"zone","document":"director","multiple":false},{"enonce":"À quelle personne du verbe se conjugue « habla » dans « ¿Usted habla francés? » ?","aide":"Usted vient de « vuestra merced ».","type":"choix","options":[{"id":"a","texte":"À la 1re personne du singulier"},{"id":"b","texte":"À la 3e personne du singulier"},{"id":"c","texte":"À la 2e personne du singulier"},{"id":"d","texte":"À la 2e personne du pluriel"}],"multiple":false},{"enonce":"Un serveur parle à plusieurs clients en Colombie. Complète.","aide":"Le verbe quieren est à la 3e personne du pluriel.","type":"trous","segments":["Señores, ¿",0," quieren un café?"],"banque":["vosotros","tú","ustedes","usted"]}]}$ex$::jsonb,
