  ('23ea32b2-8f74-57ff-9810-a31145e27299'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Madrid ou Buenos Aires ?","competence":"comprendre-langue","situation":"Camila vit à Buenos Aires, Sofía à Madrid. Elles découvrent que leurs façons de dire « tu » et « vous » ne sont pas les mêmes.","documents":[{"id":"dos","type":"dialogue","modele":"sms","titre":"Messages de Camila et Sofía","participants":[{"nom":"Camila","emoji":"👧","cote":"gauche"},{"nom":"Sofía","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Camila","texte":"¡Hola, Sofía! ¿Cómo andás? ¿Vos tenés tiempo mañana?"},{"qui":"Sofía","texte":"Sí, claro. En Madrid decimos vosotros cuando hablamos con varios amigos."},{"qui":"Camila","texte":"Aquí decimos ustedes. Y yo digo «vos sos», no «tú eres»."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom du pluriel familier qui **n’existe pas** en Amérique latine.","aide":"C’est celui que Sofía emploie à Madrid.","type":"zone","document":"dos","multiple":false},{"enonce":"Comment Camila dit-elle « tu es » ?","aide":"C’est le voseo, courant à Buenos Aires.","type":"choix","options":[{"id":"a","texte":"usted es"},{"id":"b","texte":"vos sos"},{"id":"c","texte":"tú eres"},{"id":"d","texte":"vosotros sois"}],"multiple":false},{"enonce":"Associe chaque ville aux pronoms familiers qu’on y emploie (singulier / pluriel).","aide":"Le voseo est typique de l’Argentine.","type":"association","gauche":[{"id":"g0","texte":"Madrid"},{"id":"g1","texte":"Mexico"},{"id":"g2","texte":"Buenos Aires"}],"droite":[{"id":"d0","texte":"tú / vosotros"},{"id":"d1","texte":"vos / ustedes"},{"id":"d2","texte":"tú / ustedes"}]},{"enonce":"Des amis colombiens parlent entre eux. Complète.","aide":"Le verbe vienen est à la 3e personne du pluriel.","type":"trous","segments":["¿",0," vienen al cine mañana?"],"banque":["vos","ustedes","tú","vosotros"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**vosotros** n’existe qu’en Espagne ; en Amérique latine on emploie *ustedes*, même entre amis."},{"cle":{"type":"choix","ids":["b"]},"explication":"**vos sos** : en Argentine, *vos* remplace *tú*, avec des formes propres."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Ce sont des **normes régionales**, pas des fautes."},{"cle":{"type":"trous","trous":[["ustedes"]]},"affichage":"ustedes","explication":"**ustedes vienen** : en Amérique latine, le pluriel familier est *ustedes*."}]$ex$::jsonb),
  ('23ea32b2-8f74-57ff-9810-a31145e27299'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Qui a cassé le verre ?","competence":"manier-langue","situation":"Un verre est cassé en classe : Pablo se défend. Plus tard, Elena invite Lucas au cinéma.","documents":[{"id":"vaso","type":"dialogue","modele":"sms","titre":"Messages de Marta et Pablo","participants":[{"nom":"Marta","emoji":"👧","cote":"gauche"},{"nom":"Pablo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Marta","texte":"¿Quién rompió el vaso? Nadie lo sabe."},{"qui":"Pablo","texte":"Yo no lo rompí. Fue Luis."}],"source":"Messages écrits pour l’exercice"},{"id":"cine","type":"dialogue","modele":"sms","titre":"Messages d’Elena et Lucas","participants":[{"nom":"Elena","emoji":"👧","cote":"gauche"},{"nom":"Lucas","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Elena","texte":"Esta tarde voy al cine. ¿Quieres venir conmigo?"},{"qui":"Lucas","texte":"Sí, voy contigo. Y entre tú y yo, Luis no está invitado."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche le pronom sujet que Pablo emploie pour **insister**.","aide":"Il veut bien montrer que ce n’est pas lui.","type":"zone","document":"vaso","multiple":false},{"enonce":"Pourquoi Pablo écrit-il « Yo no lo rompí » avec le pronom *yo* ?","aide":"Le verbe rompí suffit déjà à identifier la personne.","type":"choix","options":[{"id":"a","texte":"Pour insister : « moi, je ne l’ai pas cassé »"},{"id":"b","texte":"Parce que le pronom est obligatoire en espagnol"},{"id":"c","texte":"Pour lever une ambiguïté sur le verbe"},{"id":"d","texte":"Parce que le verbe rompí est au pluriel"}],"multiple":false},{"enonce":"Complète avec les pronoms soudés à *con*. Elena dit « avec moi », Lucas répond « avec toi ».","aide":"Avec con, mí et ti se soudent.","type":"trous","segments":["Elena : ¿Quieres venir ",0," al cine? Lucas : Sí, voy ",1," esta tarde."],"banque":["con yo","conmigo","con ti","contigo"]},{"enonce":"Complète avec le bon pronom après la préposition.","aide":"Entre et según gardent tú et yo ; les autres prépositions prennent mí et ti.","type":"trous","segments":["Entre ",0," y yo, no hay secretos (tu et moi). Para ",1," es fácil (pour moi). Sin ",2," no voy (sans toi)."],"banque":["mí","tú","yo","ti"]}]}$ex$::jsonb,
