  ('49b7e098-0ea0-5589-9a62-3dcee283772d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La routine d’Irene, nageuse","competence":"manier-langue","situation":"Irene, nageuse de quatorze ans, raconte sa semaine à un magazine de son collège. Un tableau résume ses habitudes.","documents":[{"id":"irene","type":"texte","genre":"article","titre":"Mi semana de nadadora","blocs":["Entrenamos de lunes a viernes. Normalmente me levanto a las seis, pero de vez en cuando me quedo en la cama.","Cuando era pequeña, solía nadar solo los sábados. Ahora sigo entrenando cada día y volví a participar en el campeonato el mes pasado."],"source":"Article écrit pour l’exercice"},{"id":"habitos","type":"tableau","titre":"Los hábitos de Irene","colonnes":["Hábito","Frecuencia"],"lignes":[["Entrenar","todos los días"],["Quedarse en la cama","de vez en cuando"],["Comer pasta antes de competir","siempre"],["Llegar tarde","casi nunca"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche le verbe qui dit l’**habitude dans le passé**.","aide":"C’est une forme de soler à l’imparfait.","type":"zone","document":"irene","multiple":false},{"enonce":"Que signifie « volví a participar en el campeonato » ?","aide":"Volver a + infinitif : on refait quelque chose une fois de plus.","type":"choix","options":[{"id":"a","texte":"Je ne participe plus au championnat"},{"id":"b","texte":"Je participe toujours au championnat"},{"id":"c","texte":"Je participais d’ordinaire au championnat"},{"id":"d","texte":"J’ai de nouveau participé au championnat"}],"multiple":false},{"enonce":"Dans le tableau, touche la fréquence de ce qu’Irene ne fait **presque jamais**.","aide":"Cherche la ligne sur le retard.","type":"zone","document":"habitos","multiple":false},{"enonce":"Associe chaque marqueur du tableau à son sens.","aide":"Todos los días embrasse l’ensemble des jours.","type":"association","gauche":[{"id":"g0","texte":"todos los días"},{"id":"g1","texte":"de vez en cuando"},{"id":"g2","texte":"siempre"},{"id":"g3","texte":"casi nunca"}],"droite":[{"id":"d0","texte":"chaque jour, sans exception"},{"id":"d1","texte":"toujours"},{"id":"d2","texte":"de temps en temps"},{"id":"d3","texte":"presque jamais"}]},{"enonce":"Les parents d’Irene ont l’habitude de dîner à neuf heures. Complète.","aide":"Le sujet est « mis padres » : 3e personne du pluriel.","type":"trous","segments":["Mis padres ",0," cenar a las nueve."],"banque":["suelen","suele","solemos","sueles"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"**Solía** : soler à l’imparfait = elle avait l’habitude de nager le samedi."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Volví a participar** : action ponctuelle répétée, « j’ai participé de nouveau »."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"**Casi nunca** : « presque jamais ». C’est la fréquence de la ligne « Llegar tarde »."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2","g3":"d3"}},"explication":"*Todos los días* = chaque jour ; *de vez en cuando* = de temps en temps ; *siempre* = toujours ; *casi nunca* = presque jamais."},{"cle":{"type":"trous","trous":[["suelen"]]},"affichage":"suelen","explication":"**Suelen cenar** : soler diphtongue (suelo, sueles, suele…, suelen) et se conjugue avec « mis padres »."}]$ex$::jsonb),
  ('da34d672-e099-5ad0-8d04-77b6cb7f2f6e'::uuid, 1, 1, 5, 20, 3,
