  ('da34d672-e099-5ad0-8d04-77b6cb7f2f6e'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le pluriel en un coup d’œil","competence":"manier-langue","situation":"La professeure d’espagnol affiche un tableau à compléter : le pluriel ne se forme pas toujours avec un simple -s.","documents":[{"id":"plural","type":"tableau","titre":"Singular y plural","colonnes":["Singular","Plural"],"lignes":[["el papel","?"],["la canción","?"],["el examen","?"],["la vez","?"],["el lunes","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Complète le tableau avec la bonne forme du pluriel.","aide":"Après une consonne : -es ; -z devient -ces ; un mot en -s non accentué sur la dernière syllabe ne change pas.","type":"trous","segments":["el papel → los ",0," ; la canción → las ",1," ; el examen → los ",2," ; la vez → las ",3," ; el lunes → los ",4],"banque":["vezes","canciones","papels","examenes","cancións","exámenes","papeles","veces","lunes"]},{"enonce":"Parmi ces noms du tableau, lequel gagne un accent écrit au pluriel ?","aide":"L’accent suit la prononciation : où tombe l’accent tonique ?","type":"choix","options":[{"id":"a","texte":"el papel"},{"id":"b","texte":"el examen"},{"id":"c","texte":"la canción"},{"id":"d","texte":"la vez"}],"multiple":false},{"enonce":"Associe chaque nom masculin à son féminin.","aide":"Certains noms ne changent pas : seul l’article varie.","type":"association","gauche":[{"id":"g0","texte":"el niño"},{"id":"g1","texte":"el profesor"},{"id":"g2","texte":"el francés"},{"id":"g3","texte":"el estudiante"}],"droite":[{"id":"d0","texte":"la estudiante"},{"id":"d1","texte":"la profesora"},{"id":"d2","texte":"la niña"},{"id":"d3","texte":"la francesa"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["papeles"],["canciones"],["examenes"],["veces"],["lunes"]]},"affichage":"papeles · canciones · exámenes · veces · lunes","explication":"**papeles, canciones, exámenes, veces, lunes** : -es après consonne, -z → -ces, et *lunes* est invariable."},{"cle":{"type":"choix","ids":["b"]},"explication":"**examen → exámenes** : l’accent apparaît pour garder la même prononciation. *canción* perd son accent (canciones)."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"On change -o en -a, on ajoute -a après -or ou -és, et *estudiante* est invariable."}]$ex$::jsonb),
  ('da34d672-e099-5ad0-8d04-77b6cb7f2f6e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une carte postale de Grenade","competence":"analyser-document","situation":"Sofía est en voyage à Grenade. Elle écrit à son amie Elena, et le professeur en tire un tableau de pluriels.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Sofía","blocs":["Querida Elena:","Granada es preciosa. El clima es seco y no hay ningún problema con el idioma: todos hablan despacio.","Ayer visité el museo y vi un cuadro con mucha sangre. Luego comí pan con miel.","Un abrazo, Sofía"],"source":"Texte écrit pour l’exercice"},{"id":"plurales","type":"tableau","titre":"Pluriels à compléter","colonnes":["Singular","Plural"],"lignes":[["la crisis","?"],["el rubí","?"],["el jueves","?"],["la luz","?"]],"enteteLignes":false,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **trois noms masculins** terminés en -a dans la lettre.","aide":"Ce sont des mots d’origine grecque : el … ma.","type":"zone","document":"carta","multiple":true},{"enonce":"Quelle phrase de Sofía est correcte ?","aide":"Color est masculin, sangre est féminin.","type":"choix","options":[{"id":"a","texte":"La color del sangre es rojo."},{"id":"b","texte":"El color de el sangre es rojo."},{"id":"c","texte":"El color de la sangre es rojo."},{"id":"d","texte":"La color de la sangre es rojo."}],"multiple":false},{"enonce":"Complète les pluriels du tableau.","aide":"Voyelle accentuée : -es. Mot en -s non accentué sur la dernière syllabe : invariable. -z : -ces.","type":"trous","segments":["la crisis → las ",0," ; el rubí → los ",1," ; el jueves → los ",2," ; la luz → las ",3],"banque":["rubíes","luzes","rubís","jueves","luces","crisis","crises"]},{"enonce":"Range chaque nom selon la formation de son pluriel.","aide":"Regarde la dernière lettre du mot.","type":"categories","categories":[{"id":"c0","texte":"+ s"},{"id":"c1","texte":"+ es"},{"id":"c2","texte":"z → ces"},{"id":"c3","texte":"Invariable"}],"items":[{"id":"i0","texte":"lunes"},{"id":"i1","texte":"lápiz"},{"id":"i2","texte":"libro"},{"id":"i3","texte":"casa"},{"id":"i4","texte":"vez"},{"id":"i5","texte":"papel"},{"id":"i6","texte":"ciudad"},{"id":"i7","texte":"crisis"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m13","m16"]},"explication":"**clima, problema, idioma** : les noms en -ma d’origine grecque sont masculins."},{"cle":{"type":"choix","ids":["c"]},"explication":"**El color de la sangre** : *el color* (masculin) et *la sangre* (féminin) ; *de el* ne s’écrit jamais."},{"cle":{"type":"trous","trous":[["crisis"],["rubies"],["jueves"],["luces"]]},"affichage":"crisis · rubíes · jueves · luces","explication":"**crisis** et **jueves** sont invariables ; **rubíes** (voyelle accentuée + -es) ; **luces** (-z → -ces)."},{"cle":{"type":"categories","items":{"i0":"c3","i1":"c2","i2":"c0","i3":"c0","i4":"c2","i5":"c1","i6":"c1","i7":"c3"}},"explication":"Voyelle → **-s** ; consonne → **-es** ; **-z → -ces** ; -s non accentué sur la dernière syllabe → **invariable**."}]$ex$::jsonb),
  ('92361de8-0e35-5522-909b-3b9527863bee'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui nettoie le tableau ?","competence":"comprendre-langue","situation":"Dans la classe d’Álex, la professeure fait des annonces par message. Les virgules changent tout.","documents":[{"id":"clase","type":"dialogue","modele":"sms","titre":"Groupe de classe","participants":[{"nom":"Profesora","emoji":"👩‍🏫","cote":"gauche"},{"nom":"Álex","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Profesora","texte":"Los alumnos que llegan tarde limpian la pizarra."},{"qui":"Álex","texte":"Yo llego tarde a veces. ¿Y mis compañeros?"},{"qui":"Profesora","texte":"Tus compañeros, que llegan temprano, ganan un punto."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Qui doit nettoyer le tableau ?","aide":"La première relative n’a pas de virgules.","type":"choix","options":[{"id":"a","texte":"Personne"},{"id":"b","texte":"Seulement les élèves qui arrivent à l’heure"},{"id":"c","texte":"Tous les élèves de la classe"},{"id":"d","texte":"Seulement les élèves qui arrivent en retard"}],"multiple":false},{"enonce":"Touche le « que » de la relative **explicative** (celle qui est entre virgules).","aide":"C’est dans le dernier message de la professeure.","type":"zone","document":"clase","multiple":false},{"enonce":"Remets en ordre : « La maison dans laquelle je vis. » La phrase commence par La.","aide":"La préposition précède toujours le relatif.","type":"ordre","items":[{"id":"a","texte":"en la que"},{"id":"b","texte":"La"},{"id":"c","texte":"casa"},{"id":"d","texte":"vivo"}]}]}$ex$::jsonb,
