   $ex$[{"cle":{"type":"zone","ids":["m7","m11","m20"]},"explication":"**hable, tenga, sepa** : l’antécédent est indéfini ou nié, donc la relative est au subjonctif."},{"cle":{"type":"choix","ids":["d"]},"explication":"**habla** : l’antécédent est connu, réel (Ana), donc on emploie l’indicatif."},{"cle":{"type":"trous","trous":[["habla"],["sepa"]]},"affichage":"habla · sepa","explication":"**que habla** (antécédent connu : indicatif) et **que sepa** (antécédent nié : subjonctif)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"L’indicatif quand on connaît la personne ; le subjonctif quand on la cherche ou qu’on nie qu’elle existe."}]$ex$::jsonb),
  ('92361de8-0e35-5522-909b-3b9527863bee'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La lettre de Diego","competence":"manier-langue","situation":"Diego écrit à sa cousine Julia depuis sa nouvelle maison. Dans sa lettre, il emploie plusieurs relatives.","documents":[{"id":"carta","type":"texte","genre":"lettre","titre":"Carta de Diego","blocs":["Querida Julia:","Mi vecino toca la trompeta de noche, lo que no nos deja dormir.","Mi hermana Rosa, quien vive en Lima, llega mañana. Los primos que viven en Cádiz llegan el domingo.","Un abrazo, Diego"],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les **deux mots** qui reprennent **toute l’idée** de la première partie de la phrase du voisin.","aide":"C’est un pronom neutre en deux mots.","type":"zone","document":"carta","multiple":true},{"enonce":"Dans la lettre, que fait la relative « quien vive en Lima » ?","aide":"Elle est entourée de virgules.","type":"choix","options":[{"id":"a","texte":"Elle remplace le sujet de la phrase principale"},{"id":"b","texte":"Elle exprime un doute à propos de Rosa et du voyage"},{"id":"c","texte":"Elle distingue Rosa des autres sœurs de Diego"},{"id":"d","texte":"Elle ajoute une information sur Rosa sans la distinguer"}],"multiple":false},{"enonce":"Remets en ordre : « Le garçon dont je parle. » La phrase commence par El.","aide":"La préposition de se place avant le relatif.","type":"ordre","items":[{"id":"a","texte":"del que"},{"id":"b","texte":"hablo"},{"id":"c","texte":"El"},{"id":"d","texte":"chico"}]},{"enonce":"Complète avec le bon relatif.","aide":"Cuyo s’accorde avec ce qui est possédé : novela.","type":"trous","segments":["El libro del ",0," te hablé es este. El escritor ",1," novela leí es famoso. Llegó tarde, ",2," me molestó."],"banque":["cuya","quien","lo que","cuyo","que"]},{"enonce":"Range chaque phrase : la relative est-elle déterminative (elle restreint) ou explicative (elle ajoute) ?","aide":"Regarde les virgules.","type":"categories","categories":[{"id":"c0","texte":"Déterminative (elle restreint)"},{"id":"c1","texte":"Explicative (elle ajoute)"}],"items":[{"id":"i0","texte":"Los vecinos, que son simpáticos, nos ayudan"},{"id":"i1","texte":"Las chicas que juegan al fútbol entrenan hoy"},{"id":"i2","texte":"Los perros que ladran mucho molestan"},{"id":"i3","texte":"Mi tía, que vive en Lima, llega mañana"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m10"]},"explication":"**lo que** reprend une idée entière (il joue de la trompette de nuit) ; on n’emploie jamais *el que* pour une phrase."},{"cle":{"type":"choix","ids":["d"]},"explication":"Entre virgules, la relative est **explicative** : elle ajoute une information. *Quien* est possible pour une personne."},{"cle":{"type":"ordre","ids":["c","d","a","b"]},"explication":"**El chico del que hablo** : *de* + *el que* se contractent en *del que*, devant le verbe."},{"cle":{"type":"trous","trous":[["que"],["cuya"],["lo que"]]},"affichage":"que · cuya · lo que","explication":"**del que**, **cuya novela** (accord avec novela, féminin) et **lo que** (il reprend la phrase entière)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Avec virgules : explicative (elle s’applique à tous). Sans virgules : déterminative (elle restreint)."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 2de (5) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
